// Einzige Stelle, die über Sichtbarkeit/Erlaubnis des Plugins entscheidet.
//
// HEUTE: Admin-only (Platform-Admins).
// SPÄTER (Kunden-Publish): entitlement-gated + per-Tenant — dann nur diese
// Funktion umstellen (Muster: cloud-services-marketplace/Marketplace.vue
// matchesEntitlements), kein verstreuter Code anderswo.
export function isAllowed(store: any): boolean {
  try {
    if (store.getters['auth/isAdmin']) {
      return true;
    }
    // Best-effort über die geladenen Rollen; falls Getter abweicht, fail-closed.
    const roles =
      store.getters['auth/roles'] ||
      store.getters['auth/principalRoles'] ||
      [];
    if (Array.isArray(roles) && roles.some((r: any) => `${r}`.toLowerCase().includes('admin'))) {
      return true;
    }
  } catch (e) {
    // fail closed
  }
  return false;

  // --- Kunden-Modus (später aktivieren) ---
  // const ent = readEntitlements(store);
  // return ent.geoRedundantK8s === true;
}
