// Rendert die Manifeste für einen gestreckten Multi-Insel-RKE2-Cluster.
//
// Erzeugt je Zone EINE HarvesterConfig + EINEN provisioning.cattle.io Cluster.
// Kern (warum die Standard-UI das nicht kann):
//   - per-Pool cloudCredentialSecretName  (jede Zone = eigene Harvester-Insel)
//   - cloud-provider-name: external       (kein Harvester-CCM über mehrere Inseln)
//   - KEIN harvester-cloud-provider chartValues-Block
//   - KEIN machineSelectorConfig.cloud-provider-config
import blueprints from '../data/blueprints.json';

export interface ZoneSpec {
  zone: string;          // 'b1' | 'b2' | 'han'
  credentialId: string;  // z.B. 'cc-nxbxd' (ohne cattle-global-data: Präfix)
  vmNamespace: string;
  networkName: string;   // z.B. 'shared-k8s/fcs-backend-vm-net'
  image: string;         // z.B. 'default/image-zrfv4'
  sshUser?: string;      // Cloud-Image-User (SLE Micro=sles, Ubuntu=ubuntu, …); Default 'sles'
  // EFI-Boot-Fähigkeit ist image-/insel-abhängig (PoC-Befund: dasselbe Leap-Micro-Image
  // bootete auf dev nur mit enableEfi=false, auf DC2 nur mit true — Root-Cause offen,
  // siehe docs/reviews/SFH_MULTISITE_POC_FINDINGS). Wizard leitet es aus dem Image ab;
  // Default true (Plan-Vorgabe), aber NICHT hart erzwingen.
  enableEfi?: boolean;
  cpu: number;
  mem: number;           // GiB
  disk: number;          // GiB
  cpQuantity: number;    // etcd+controlplane Nodes (0 = keine)
  workerCount: number;   // Worker Nodes (0 = keine)
  etcdOnly?: boolean;    // Tiebreaker: 1 etcd-Voter, getaintet, kein cp/worker
}

export interface ClusterSpec {
  name: string;
  k8sVersion: string;
  podCidr: string;
  serviceCidr: string;
  routingMode: 'native' | 'tunnel';
  zones: ZoneSpec[];
}

const GD = 'cattle-global-data:';

function harvesterConfig(spec: ClusterSpec, z: ZoneSpec) {
  return {
    apiVersion: 'rke-machine-config.cattle.io/v1',
    kind:       'HarvesterConfig',
    metadata:   { name: `nc-${spec.name}-${z.zone}`, namespace: 'fleet-default' },
    cpuCount:   String(z.cpu),
    memorySize: String(z.mem),
    diskBus:    'virtio',
    diskInfo:   JSON.stringify({ disks: [{ imageName: z.image, bootOrder: 1, size: z.disk }] }),
    diskSize:   '0',
    // EFI ist image-/insel-abhängig (s. ZoneSpec.enableEfi) — Default true, aber überschreibbar.
    enableEfi:        z.enableEfi ?? true,
    enableSecureBoot: false,
    enableTpm:        false,
    networkInfo: JSON.stringify({ interfaces: [{ networkName: z.networkName }] }),
    vmNamespace: z.vmNamespace,
    // Muss zum gewählten Cloud-Image passen, sonst scheitert der Rancher-Machine-
    // Bootstrap über SSH (CMR-High): SLE/Leap Micro=sles, Ubuntu=ubuntu, …
    sshUser:     z.sshUser || 'sles',
    userData: [
      '#cloud-config',
      'package_update: true',
      'packages:',
      '  - qemu-guest-agent',
      // SLE-Micro: health-checker.service bildet sonst einen systemd-Zyklus, der
      // cloud-init/Bootstrap blockiert — Fix übernommen aus Referenz prod-01.
      'bootcmd:',
      '  - |',
      '    mkdir -p /etc/systemd/system/health-checker.service.d',
      "    printf '[Unit]\\nAfter=\\n' > /etc/systemd/system/health-checker.service.d/no-cycle.conf",
      '    systemctl daemon-reload',
      '    systemctl start --no-block cloud-final.service || true',
      'runcmd:',
      "  - [systemctl, enable, '--now', qemu-guest-agent.service]",
      '',
    ].join('\n'),
  };
}

function machinePools(spec: ClusterSpec) {
  const out: any[] = [];
  for (const z of spec.zones) {
    const cred = GD + z.credentialId;
    const ref = { kind: 'HarvesterConfig', name: `nc-${spec.name}-${z.zone}` };
    const labels = { 'topology.kubernetes.io/zone': z.zone };

    if (z.etcdOnly) {
      out.push({
        name: `etcd-${z.zone}`, etcdRole: true, controlPlaneRole: false, workerRole: false,
        quantity: 1, drainBeforeDelete: true, cloudCredentialSecretName: cred,
        machineConfigRef: ref, labels,
        taints: [{ key: 'node-role.kubernetes.io/etcd', value: 'true', effect: 'NoExecute' }],
      });
      continue;
    }
    if (z.cpQuantity > 0) {
      out.push({
        name: `cp-${z.zone}`, etcdRole: true, controlPlaneRole: true, workerRole: false,
        quantity: z.cpQuantity, drainBeforeDelete: true, cloudCredentialSecretName: cred,
        machineConfigRef: ref, labels,
      });
    }
    if (z.workerCount > 0) {
      out.push({
        name: `wk-${z.zone}`, etcdRole: false, controlPlaneRole: false, workerRole: true,
        quantity: z.workerCount, drainBeforeDelete: true, cloudCredentialSecretName: cred,
        machineConfigRef: ref, labels,
      });
    }
  }
  return out;
}

// In-Cluster-Taint-Resolver für `cloud-provider-name: external` (Pflicht im Multi-Site-
// Manifest, da kein einzelner Harvester-CCM über Inseln spannt). Ohne CCM lässt der
// kubelet den `node.cloudprovider.kubernetes.io/uninitialized:NoSchedule`-Taint stehen
// → cattle-cluster-agent bleibt Pending → Rancher-"waiting for node"-Timeout → Machine-
// Delete-Recreate-Churn (im PoC verifiziert). Externe Taint-Removal gewinnt das Rennen
// NICHT — der Resolver muss IN-CLUSTER laufen. Wird via RKE2 `additionalManifest` auf den
// Server-Nodes ausgerollt; der DaemonSet toleriert ALLE Taints und schedult deshalb sofort
// auf jeden (auch frisch getainteten) Node und räumt den Taint laufend ab.
function taintResolverManifest(k8sVersion: string): string {
  // Image MUSS eine POSIX-Shell UND kubectl enthalten (CMR-P1): rancher/kubectl ist
  // minimal/distroless (nur /bin/kubectl, KEIN /bin/sh) → die `/bin/sh -c`-Resolver-Loop
  // crasht (CrashLoopBackOff), der Taint bleibt stehen. bitnami/kubectl wäre shell-fähig,
  // ist aber seit der Bitnami-2025-Restriktion auf Docker Hub 404 (auch bitnamilegacy).
  // alpine/k8s (Alpine-Base → /bin/sh, bringt kubectl) existiert multi-arch + frei.
  // Tag ohne führendes 'v' und ohne '+rke2…'-Suffix (alpine/k8s-Tag-Format: 1.34.4).
  const kubectlTag = k8sVersion.replace(/^v/, '').replace(/\+.*$/, ''); // v1.34.4+rke2r1 -> 1.34.4
  return [
    'apiVersion: v1',
    'kind: ServiceAccount',
    'metadata: { name: uninitialized-taint-remover, namespace: kube-system }',
    '---',
    'apiVersion: rbac.authorization.k8s.io/v1',
    'kind: ClusterRole',
    'metadata: { name: uninitialized-taint-remover }',
    'rules:',
    '  - apiGroups: [""]',
    '    resources: ["nodes"]',
    '    verbs: ["get", "list", "watch", "patch"]',
    '---',
    'apiVersion: rbac.authorization.k8s.io/v1',
    'kind: ClusterRoleBinding',
    'metadata: { name: uninitialized-taint-remover }',
    'roleRef: { apiGroup: rbac.authorization.k8s.io, kind: ClusterRole, name: uninitialized-taint-remover }',
    'subjects: [{ kind: ServiceAccount, name: uninitialized-taint-remover, namespace: kube-system }]',
    '---',
    'apiVersion: apps/v1',
    'kind: DaemonSet',
    'metadata: { name: uninitialized-taint-remover, namespace: kube-system }',
    'spec:',
    '  selector: { matchLabels: { app: uninitialized-taint-remover } }',
    '  template:',
    '    metadata: { labels: { app: uninitialized-taint-remover } }',
    '    spec:',
    '      serviceAccountName: uninitialized-taint-remover',
    '      hostNetwork: true',
    '      priorityClassName: system-node-critical',
    '      tolerations: [{ operator: Exists }]', // toleriert ALLE Taints inkl. uninitialized
    '      containers:',
    '        - name: remover',
    `          image: alpine/k8s:${kubectlTag}`,
    '          command: ["/bin/sh", "-c"]',
    '          args:',
    '            - |',
    '              while true; do',
    '                kubectl taint nodes --all node.cloudprovider.kubernetes.io/uninitialized- >/dev/null 2>&1 || true',
    '                sleep 30',
    '              done',
    '          resources: { requests: { cpu: 10m, memory: 16Mi }, limits: { cpu: 50m, memory: 64Mi } }',
    '',
  ].join('\n');
}

export function render(spec: ClusterSpec) {
  const bp: any = blueprints;
  const harvesterConfigs = spec.zones.map((z) => harvesterConfig(spec, z));

  const cluster = {
    apiVersion: 'provisioning.cattle.io/v1',
    kind:       'Cluster',
    metadata:   {
      name:      spec.name,
      namespace: 'fleet-default',
      labels:    { 'focusnet.de/stretch-host': 'true' },
      annotations: { 'field.cattle.io/description': 'Multi-Site stretched RKE2 (focusnet)' },
    },
    spec: {
      cloudCredentialSecretName: GD + spec.zones[0].credentialId,
      kubernetesVersion:         spec.k8sVersion,
      enableNetworkPolicy:       true,
      rkeConfig: {
        machineGlobalConfig: {
          cni:                  'cilium',
          'cloud-provider-name': 'external',
          'disable-kube-proxy':  true,
          'cluster-cidr':        spec.podCidr,
          'service-cidr':        spec.serviceCidr,
          'etcd-arg':            bp.etcdArgs,
        },
        chartValues: {
          // bp.ciliumValues setzt k8sServiceHost=127.0.0.1 / k8sServicePort=6443 (PFLICHT):
          // mit disable-kube-proxy + kubeProxyReplacement gibt es beim Bootstrap weder
          // kube-proxy noch ein laufendes Cilium, das die kubernetes-ClusterIP (…43.0.1)
          // routet → Cilium-Operator/-Agent erreichen den apiserver sonst NICHT
          // ("no route to host") → CNI-Deadlock, Node NotReady (im PoC live verifiziert).
          // 127.0.0.1:6443 = RKE2-lokaler apiserver/Agent-LB auf JEDEM Node.
          'rke2-cilium': { ...bp.ciliumValues, routingMode: spec.routingMode },
        },
        machinePools:    machinePools(spec),
        upgradeStrategy: bp.upgradeStrategy,
        // Pflicht bei cloud-provider-name: external — entfernt den uninitialized-Taint
        // in-cluster (sonst Churn, im §7#2-PoC verifiziert). Siehe taintResolverManifest().
        additionalManifest: taintResolverManifest(spec.k8sVersion),
      },
    },
  };

  return { harvesterConfigs, cluster };
}
