<script>
import blueprints from '../data/blueprints.json';
import { validate } from '../lib/invariants';
import { render } from '../lib/renderManifest';
import {
  listHarvesterCredentials,
  postMachineConfig,
  postCluster,
  getClusterStatus,
} from '../lib/steve';

function defaultZone(zone) {
  return {
    zone,
    credentialId: '',
    vmNamespace:  'default',
    networkName:  'shared-k8s/fcs-backend-vm-net',
    image:        '',
    sshUser:      'sles',
    // EFI-Boot pro Zone setzbar — image-/insel-abhängig (PoC-Befund: gleiches
    // Leap-Micro-Image bootete dev nur mit false, DC2 mit true; Root-Cause offen).
    // Default true (Plan-Vorgabe); für betroffene dev-Images abwählen.
    enableEfi:    true,
    cpu:          4,
    mem:          8,
    disk:         40,
    cpQuantity:   zone === 'b1' ? 2 : 1,
    workerCount:  1,
    etcdOnly:     false,
  };
}

export default {
  name:   'ProvisionWizard',
  layout: 'plain',

  data() {
    return {
      spec: {
        name:        'sfh-stretch-poc',
        k8sVersion:  blueprints.defaultK8sVersion,
        podCidr:     blueprints.defaultPodCidr,
        serviceCidr: blueprints.defaultServiceCidr,
        routingMode: 'tunnel',
        zones:       [defaultZone('b1'), defaultZone('b2')],
      },
      credentials:  [],
      errors:       [],
      log:          [],
      busy:         false,
      loadingCreds: true,
    };
  },

  async mounted() {
    try {
      this.credentials = await listHarvesterCredentials(this.$store);
    } catch (e) {
      this.errors = [`Cloud-Credentials konnten nicht geladen werden: ${ e?.message || e }`];
    } finally {
      this.loadingCreds = false;
    }
  },

  methods: {
    addZone() {
      this.spec.zones.push(defaultZone(`z${ this.spec.zones.length + 1 }`));
    },
    removeZone(i) {
      this.spec.zones.splice(i, 1);
    },
    validateNow() {
      this.errors = validate(this.spec);
      return this.errors.length === 0;
    },
    push(m) {
      this.log.push(m);
    },
    previewManifest() {
      if (!this.validateNow()) {
        return;
      }
      const { harvesterConfigs, cluster } = render(this.spec);
      this.log = [JSON.stringify({ harvesterConfigs, cluster }, null, 2)];
    },
    async createCluster() {
      if (!this.validateNow()) {
        return;
      }
      this.busy = true;
      this.log = [];
      try {
        const { harvesterConfigs, cluster } = render(this.spec);
        for (const hc of harvesterConfigs) {
          // postMachineConfig upsertet (POST, bei 409 PUT) -> keine stale Config.
          this.push(`Upsert HarvesterConfig ${ hc.metadata.name } ...`);
          await postMachineConfig(this.$store, hc);
        }
        this.push(`POST Cluster ${ cluster.metadata.name } ...`);
        await postCluster(this.$store, cluster);
        this.push('Cluster-Provisioning angestoßen. Warte auf status.ready ...');
        for (let i = 0; i < 90; i++) {
          await new Promise((r) => setTimeout(r, 10000));
          const s = await getClusterStatus(this.$store, cluster.metadata.name);
          this.push(`  [${ i }] ready=${ s.ready }`);
          if (s.ready) {
            this.push('Cluster ist Ready ✅');
            break;
          }
        }
      } catch (e) {
        this.errors = [`Fehler: ${ e?.message || e }`];
      } finally {
        this.busy = false;
      }
    },
  },
};
</script>

<template>
  <div class="msp">
    <header class="msp__header">
      <h1>Multi-Site Cluster Provisioner</h1>
      <p>Gestreckter RKE2-Cluster über mehrere Harvester-Inseln (per-Pool-Credential, <code>cloud-provider-name: external</code>).</p>
    </header>

    <div
      v-if="errors.length"
      class="msp__errors"
    >
      <strong>Bitte korrigieren:</strong>
      <ul>
        <li
          v-for="(err, i) in errors"
          :key="i"
        >
          {{ err }}
        </li>
      </ul>
    </div>

    <section class="msp__cluster">
      <label>Cluster-Name <input v-model="spec.name"></label>
      <label>Kubernetes-Version <input v-model="spec.k8sVersion"></label>
      <label>Pod-CIDR <input v-model="spec.podCidr"></label>
      <label>Service-CIDR <input v-model="spec.serviceCidr"></label>
      <label>Routing
        <select v-model="spec.routingMode">
          <option value="tunnel">tunnel (PoC)</option>
          <option value="native">native+BGP (PROD)</option>
        </select>
      </label>
    </section>

    <h2>Zonen (= Harvester-Inseln)</h2>
    <table class="msp__zones">
      <thead>
        <tr>
          <th>Zone</th><th>Cloud-Credential</th><th>VM-NS</th><th>Network</th>
          <th>Image</th><th>sshUser</th><th title="EFI-Boot — image-/insel-abhängig (manche dev-Images brauchen EFI=aus)">EFI</th><th>vCPU</th><th>GiB</th><th>Disk</th><th>CP</th><th>Worker</th><th>etcd-only</th><th></th>
        </tr>
      </thead>
      <tbody>
        <tr
          v-for="(z, i) in spec.zones"
          :key="i"
        >
          <td><input v-model="z.zone" size="4"></td>
          <td>
            <select
              v-model="z.credentialId"
              :disabled="loadingCreds"
            >
              <option value="">
                — wählen —
              </option>
              <option
                v-for="c in credentials"
                :key="c.id"
                :value="c.id"
              >
                {{ c.name }} ({{ c.id }})
              </option>
            </select>
          </td>
          <td><input v-model="z.vmNamespace" size="8"></td>
          <td><input v-model="z.networkName" size="18"></td>
          <td><input v-model="z.image" size="14" placeholder="default/image-…"></td>
          <td><input v-model="z.sshUser" size="6"></td>
          <td><input
            v-model="z.enableEfi"
            type="checkbox"
          ></td>
          <td><input
            v-model.number="z.cpu"
            type="number"
            size="2"
          ></td>
          <td><input
            v-model.number="z.mem"
            type="number"
            size="2"
          ></td>
          <td><input
            v-model.number="z.disk"
            type="number"
            size="3"
          ></td>
          <td><input
            v-model.number="z.cpQuantity"
            type="number"
            size="2"
          ></td>
          <td><input
            v-model.number="z.workerCount"
            type="number"
            size="2"
          ></td>
          <td><input
            v-model="z.etcdOnly"
            type="checkbox"
          ></td>
          <td><button @click="removeZone(i)">
            ✕
          </button></td>
        </tr>
      </tbody>
    </table>
    <button @click="addZone">
      + Zone
    </button>

    <div class="msp__actions">
      <button
        :disabled="busy"
        @click="previewManifest"
      >
        Manifest-Vorschau
      </button>
      <button
        class="msp__primary"
        :disabled="busy"
        @click="createCluster"
      >
        {{ busy ? 'Provisioniere …' : 'Cluster anlegen' }}
      </button>
    </div>

    <pre
      v-if="log.length"
      class="msp__log"
    >{{ log.join('\n') }}</pre>
  </div>
</template>

