import { IPlugin } from '@shell/core/types';
import { isAllowed } from './lib/gate';

export const NAME = 'multisite-cluster-provisioner';

export function init($plugin: IPlugin, store: any) {
  const { product } = $plugin.DSL(store, NAME);

  // Gate: heute Admin-only (lib/gate.ts). Produkt nur registrieren, wenn erlaubt.
  // Kunden-Publish später = isAllowed() auf entitlement-gated umstellen.
  let allowed = false;
  try {
    allowed = isAllowed(store);
  } catch (e) {
    allowed = false; // fail closed
  }
  if (!allowed) {
    return;
  }

  product({
    inStore:             'management',
    icon:                'globe',
    label:               'Multi-Site Cluster Provisioner',
    removable:           false,
    showClusterSwitcher: false,
    category:            'global',
    to:                  { name: NAME },
  } as any);
}
